head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > P > tabIndex]<br/>Tab 키를 사용하여 컴포넌트 간 포커스를 이동할 때 컴포넌트의 순서를 설정합니다.",
    "validation" : [        
        "outerDiv=true 이면 div 태그와 a 태그의 tabIndex 속성에 같은값이 설정 되어야 합니다.",
        "useChild=true 일때 자식 컴포넌트에는 tabIndex 속성이 설정되지 않아야 합니다.",
    ]
} 



scwin.onpageload = function () {
    // let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    $c.gcm.createCommonDatalist();

    // // comp 초기 생성
    // scwin.comp_init();
};



scwin.getTabIndex_onclick = function (e) {
    let rtn = '';

    rtn = target1.render.tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("target1 div: "+rtn)

    rtn = target1.render.childNodes[0].tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("target1 a: "+rtn)  

    rtn = target2.render.tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("target2 div: "+rtn)

    rtn = target2.render.childNodes[0].tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("target2 a: "+rtn)

    rtn = target2.render.childNodes[0].childNodes[0].tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("target2 span: "+rtn)  
};
